57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    private final AddressNormalizer addressNormalizer;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper,
80	                                 AddressNormalizer addressNormalizer) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	        this.addressNormalizer = addressNormalizer;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = addressNormalizer.normalize(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setTelephone(telephone);
128	        LocalDate effectiveDate = owner.getRegistrationDate() != null
129	            ? owner.getRegistrationDate() : LocalDate.now();
130	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
131	        if (isDailyLimitReached(owner.getRegistrationDate())) {
132	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
133	        }
134	        if (isTelephoneInUse(telephone)) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
138	        if (!sharesHousehold && isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
139	            return new ResponseEntity<>(HttpStatus.CONFLICT);
140	        }
141	        if (sharesHousehold) {
142	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
143	        }
144	        if (isCityAtCapacity(owner.getCity())) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
148	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
149	        this.clinicService.saveOwner(owner);
150	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
151	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
152	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
153	        headers.setLocation(UriComponentsBuilder.newInstance()
154	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
155	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
156	    }
157	
158	    /**
159	     * Build the customer code for a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
160	     * where CITY3 is the upper-cased first three letters of {@code city}, LAST3 the upper-cased first
161	     * three letters of {@code lastName} and NNNN a per-city 4-digit zero-padded sequence equal to one
162	     * more than the number of owners already in that city (e.g. {@code 'LON-SMI-0007'}).
163	     */
164	    private String nextCustomerCode(String city, String lastName) {
165	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
166	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
167	        int sequence = (int) this.clinicService.findAllOwners().stream()
168	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
169	            .count() + 1;
170	        return String.format("%s-%s-%04d", city3, last3, sequence);
171	    }
172	
173	    /**
174	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
175	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
176	     * (business-day) registration date of the owner being created, so owners are counted per
177	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
178	     */
179	    private boolean isDailyLimitReached(LocalDate day) {
180	        long count = this.clinicService.findAllOwners().stream()
181	            .filter(existing -> day.equals(existing.getRegistrationDate()))
182	            .count();
183	        return count >= 100;
184	    }
185	
186	    /**
187	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
188	     * advance it to the following Monday; a weekday is returned unchanged.
189	     */
190	    private LocalDate toBusinessDay(LocalDate date) {
191	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
192	            date = date.plusDays(1);
193	        }
194	        return date;
195	    }
196	
197	    /**
198	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
199	     * more owners. Cities are compared case-insensitively, matching {@link #nextCustomerCode}.
200	     */
201	    private boolean isCityAtCapacity(String city) {
202	        long count = this.clinicService.findAllOwners().stream()
203	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
204	            .count();
205	        return count >= 50;
206	    }
207	
208	    /**
209	     * The number of existing owners that already share the given firstName and lastName,
210	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
211	     * whitespace runs collapsed). Counted over the owners present before this create.
212	     */
213	    private int namesakeCount(String firstName, String lastName) {
214	        String candidateFirstName = normalizeName(firstName);
215	        String candidateLastName = normalizeName(lastName);
216	        return (int) this.clinicService.findAllOwners().stream()
217	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
218	                && normalizeName(existing.getLastName()).equals(candidateLastName))
219	            .count();
220	    }
221	
222	    /**
223	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
224	     * cannot form a valid E.164 number.
225	     *
226	     * <p>A leading '+' and country code are kept when present; otherwise country code
227	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
228	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
229	     * carry 8 to 15 digits after the '+'.
230	     */
231	    private String toE164(String telephone) {
232	        if (telephone == null) {
233	            return null;
234	        }
235	        boolean hasCountryCode = telephone.trim().startsWith("+");
236	        String digits = telephone.replaceAll("\\D", "");
237	        String e164;
238	        if (hasCountryCode) {
239	            e164 = digits;
240	        } else {
241	            if (digits.startsWith("0")) {
242	                digits = digits.substring(1);
243	            }
244	            e164 = "61" + digits;
245	        }
246	        if (e164.length() < 8 || e164.length() > 15) {
247	            return null;
248	        }
249	        return "+" + e164;
250	    }
251	
252	    /**
253	     * Whether any existing owner already holds the given telephone number. Both the
254	     * candidate and each stored number are compared in E.164 form, so the check does not
255	     * depend on how each was originally formatted.
256	     */
257	    private boolean isTelephoneInUse(String telephone) {
258	        return this.clinicService.findAllOwners().stream()
259	            .map(Owner::getTelephone)
260	            .filter(Objects::nonNull)
261	            .map(this::toE164)
262	            .filter(Objects::nonNull)
263	            .anyMatch(telephone::equals);
264	    }
265	
266	    /**
267	     * Whether any existing owner already shares a household with the candidate, i.e. has both
268	     * the same lastName and the same address. Both fields are compared case-insensitively and
269	     * with internal runs of whitespace collapsed to a single space (and surrounding whitespace
270	     * trimmed), so the check does not depend on casing or spacing.
271	     */
272	    private boolean isHouseholdInUse(String lastName, String address) {
273	        String candidateLastName = normalizeName(lastName);
274	        String candidateAddress = addressNormalizer.normalize(address);
275	        return this.clinicService.findAllOwners().stream()
276	            .anyMatch(existing -> normalizeName(existing.getLastName()).equals(candidateLastName)
277	                && addressNormalizer.normalize(existing.getAddress()).equals(candidateAddress));
278	    }
279	
280	    /**
281	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
282	     * to a single space and lower-case. A null value normalizes to the empty string.
283	     */
284	    private String normalizeName(String value) {
285	        if (value == null) {
286	            return "";
287	        }
288	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
289	    }
290	
291	    /**
292	     * A stable shared identifier for the household formed by a given lastName and address.
293	     * Derived deterministically from the normalized (case-insensitive, whitespace-collapsed)
294	     * lastName and address, so every owner sharing the same household is assigned the same
295	     * value regardless of the order in which they are created. Formatted as the first 12
296	     * upper-case hex characters of the SHA-256 of {@code '<lastName>|<address>'}.
297	     */
298	    private String householdId(String lastName, String address) {
299	        String key = normalizeName(lastName) + "|" + addressNormalizer.normalize(address);
300	        try {
301	            byte[] digest = MessageDigest.getInstance("SHA-256")
302	                .digest(key.getBytes(StandardCharsets.UTF_8));
303	            StringBuilder sb = new StringBuilder(digest.length * 2);
304	            for (byte b : digest) {
305	                sb.append(String.format("%02x", b));
306	            }
307	            return sb.substring(0, 12).toUpperCase();
308	        }
309	        catch (NoSuchAlgorithmException e) {
310	            throw new IllegalStateException("SHA-256 not available", e);
311	        }
312	    }
313	
314	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
315	    @Override
316	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
317	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
318	        if (currentOwner == null) {
319	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	        }
321	        currentOwner.setAddress(ownerFieldsDto.getAddress());
322	        currentOwner.setCity(ownerFieldsDto.getCity());
323	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
324	        currentOwner.setLastName(ownerFieldsDto.getLastName());
325	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
326	        this.clinicService.saveOwner(currentOwner);
327	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
328	    }
329	
330	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
331	    @Transactional
332	    @Override
333	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
334	        Owner owner = this.clinicService.findOwnerById(ownerId);
335	        if (owner == null) {
336	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
337	        }
338	        this.clinicService.deleteOwner(owner);
339	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
340	    }
341	
342	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
343	    @Override
344	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
345	        Owner owner = this.clinicService.findOwnerById(ownerId);
346	        if (owner == null) {
347	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
348	        }
349	        HttpHeaders headers = new HttpHeaders();
350	        Pet pet = petMapper.toPet(petFieldsDto);
351	        owner.setId(ownerId);
352	        pet.setOwner(owner);
353	        pet.getType().setName(null);
354	        this.clinicService.savePet(pet);
355	        PetDto petDto = petMapper.toPetDto(pet);
356	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
357	            .buildAndExpand(pet.getId()).toUri());
358	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
359	    }
360	
361	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
362	    @Override
363	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
364	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
365	        if (currentOwner != null) {
366	            Pet currentPet = this.clinicService.findPetById(petId);
367	            if (currentPet != null) {
368	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
369	                currentPet.setName(petFieldsDto.getName());
370	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
371	                this.clinicService.savePet(currentPet);
372	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
373	            }
374	        }
375	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
376	    }
377	
378	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
379	    @Override
380	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
381	        HttpHeaders headers = new HttpHeaders();
382	        Visit visit = visitMapper.toVisit(visitFieldsDto);
383	        Pet pet = new Pet();
384	        pet.setId(petId);
385	        visit.setPet(pet);
386	        this.clinicService.saveVisit(visit);
387	        VisitDto visitDto = visitMapper.toVisitDto(visit);
388	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
389	            .buildAndExpand(visit.getId()).toUri());
390	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
391	    }
392	
393	
394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Override
396	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
397	        Owner owner = this.clinicService.findOwnerById(ownerId);
398	        if (owner != null) {
399	            Pet pet = owner.getPet(petId);
400	            if (pet != null) {
401	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
402	            }
403	        }
404	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
405	    }
406	}
